// The $ROT ruleset, in the browser.
//
// This is a line-for-line mirror of src/math.rs, in BigInt so the rounding
// matches exactly. It exists so the page can fast-forward the economy sixty
// days without touching a chain, and so a visitor can watch their balance fall
// between blocks instead of waiting for someone to poke it.
//
// selfTest() asserts the vectors in vectors.js, which are generated by the
// Python simulation and asserted by `cargo test` too. If this file ever drifts
// from the contract, the badge at the top of the page goes red.

(function (global) {
  "use strict";

  const BPS = 10000n;
  const PRECISION = 10n ** 18n;

  // BigInt division truncates toward zero and every value here is
  // non-negative, so this is the same floor the contract does in 256 bits.
  function mulDiv(a, b, d) {
    if (d === 0n) throw new Error("math: division by zero");
    return (a * b) / d;
  }

  function rotDays(settledDay, protectedUntil, nowDay) {
    const first = settledDay + 1n > protectedUntil ? settledDay + 1n : protectedUntil;
    return nowDay >= first ? nowDay - first + 1n : 0n;
  }

  function survivalFactor(rotBpsPerDay, days) {
    if (rotBpsPerDay > BPS) throw new Error("math: rot_bps > 100%");
    let base = PRECISION - mulDiv(PRECISION, rotBpsPerDay, BPS);
    let result = PRECISION;
    let n = days;
    while (n > 0n) {
      if (n & 1n) result = mulDiv(result, base, PRECISION);
      n >>= 1n;
      if (n === 0n) break;
      base = mulDiv(base, base, PRECISION);
      if (base === 0n) return 0n;
    }
    return result;
  }

  function applyRot(balance, rotBpsPerDay, days) {
    if (balance === 0n || days === 0n || rotBpsPerDay === 0n) {
      return { after: balance, rotted: 0n };
    }
    const after = mulDiv(balance, survivalFactor(rotBpsPerDay, days), PRECISION);
    return { after, rotted: balance - after };
  }

  function stampCost(balance, stampCostBps) {
    if (balance === 0n || stampCostBps === 0n) return 0n;
    let cost = mulDiv(balance, stampCostBps, BPS);
    if (cost === 0n) cost = 1n;
    return cost < balance ? cost : balance;
  }

  function compostShare(compost, stake, balanceNow, weight) {
    if (compost === 0n || weight === 0n) return 0n;
    let effective = stake < balanceNow ? stake : balanceNow;
    // One holder cannot be more than all of them.
    if (effective > weight) effective = weight;
    if (effective === 0n) return 0n;
    return mulDiv(compost, effective, weight);
  }

  function dayOf(nowMs, genesisMs, dayMs) {
    if (nowMs <= genesisMs) return 0n;
    return (nowMs - genesisMs) / dayMs;
  }

  function epochOf(day, epochDays) {
    return day / epochDays;
  }

  // ---------------------------------------------------------------------
  // The playground: run the whole economy forward, in here.
  // ---------------------------------------------------------------------

  const ONE = 10n ** 18n;

  /**
   * Replays the same loop as sim/simulate.py.
   * opts: { days, holders, participation, rotBps, stampCostBps, stampDays,
   *         epochDays, faucet, whale }
   * Returns one row per day for charting.
   */
  function simulate(opts) {
    const days = opts.days ?? 60;
    const n = opts.holders ?? 10;
    const participation = opts.participation ?? 0.5;
    const rotBps = BigInt(opts.rotBps ?? 200);
    const costBps = BigInt(opts.stampCostBps ?? 50);
    const stampDays = BigInt(opts.stampDays ?? 7);
    const epochDays = BigInt(opts.epochDays ?? 7);
    const faucet = opts.faucet ?? 1000n * ONE;
    const whale = opts.whale ?? 0; // extra multiples of the faucet for holder 0

    // How many holders stamp, rounded to whole people.
    const stampers = Math.round(n * participation);

    const holders = [];
    let minted = 0n;
    for (let i = 0; i < n; i++) {
      let bal = faucet;
      if (i === 0 && whale > 0) bal += BigInt(whale) * faucet;
      minted += bal;
      holders.push({
        balance: bal,
        start: bal,
        settledDay: 0n,
        protectedUntil: 0n,
        stamps: new Map(), // epoch -> { stake, claimed }
        stamper: i < stampers,
        paidInStamps: 0n,
      });
    }

    let burned = 0n;
    let composted = 0n;
    const epochWeight = new Map();
    const epochCompost = new Map();
    const rows = [];

    const get = (m, k) => m.get(k) ?? 0n;

    for (let d = 0; d <= days; d++) {
      const day = BigInt(d);
      const epoch = epochOf(day, epochDays);

      const settle = (h) => {
        const dd = rotDays(h.settledDay, h.protectedUntil, day);
        const { after, rotted } = applyRot(h.balance, rotBps, dd);
        h.balance = after;
        if (day > h.settledDay) h.settledDay = day;
        if (rotted > 0n) {
          if (get(epochWeight, epoch) === 0n) {
            burned += rotted; // nobody stamped, so it burns
          } else {
            epochCompost.set(epoch, get(epochCompost, epoch) + rotted);
            composted += rotted;
          }
        }
      };

      // 1. stamps
      for (const h of holders) {
        if (!h.stamper || d % Number(stampDays) !== 0) continue;
        settle(h);
        if (h.balance === 0n) continue;
        const cost = stampCost(h.balance, costBps);
        if (cost >= h.balance) continue;
        h.balance -= cost;
        burned += cost;
        h.paidInStamps += cost;
        const until = day + stampDays;
        if (until > h.protectedUntil) h.protectedUntil = until;

        const earn = epoch + 1n;
        const prev = h.stamps.get(earn);
        if (prev) {
          // Replace, do not add: the second stamp cost another slice.
          const old = prev.stake;
          prev.stake = h.balance;
          const w = get(epochWeight, earn);
          epochWeight.set(earn, (w > old ? w - old : 0n) + h.balance);
        } else {
          h.stamps.set(earn, { stake: h.balance, claimed: 0n, settled: false });
          epochWeight.set(earn, get(epochWeight, earn) + h.balance);
        }
      }

      // 2. claims
      for (const h of holders) {
        settle(h);
        let total = 0n;
        for (const [e, rec] of h.stamps) {
          // A finished heap never changes, so one visit settles the stake.
          if (rec.settled || e >= epoch) continue;
          rec.settled = true;
          const compost = get(epochCompost, e);
          const weight = get(epochWeight, e);
          if (compost === 0n || weight === 0n) continue;
          const owed = compostShare(compost, rec.stake, h.balance, weight);
          if (owed === 0n) continue;
          rec.claimed = owed;
          total += owed;
        }
        if (total > 0n) {
          h.balance += total;
          composted -= total;
        }
      }

      // 3. a rational poker settles everyone
      for (const h of holders) settle(h);

      const stampedBal = holders
        .filter((h) => h.protectedUntil > day)
        .reduce((a, h) => a + h.balance, 0n);
      const idleBal = holders
        .filter((h) => h.protectedUntil <= day)
        .reduce((a, h) => a + h.balance, 0n);

      rows.push({
        day: d,
        totalSupply: toFloat(minted - burned),
        burned: toFloat(burned),
        composted: toFloat(composted),
        stampedBalance: toFloat(stampedBal),
        idleBalance: toFloat(idleBal),
        avgStamper: avg(holders.filter((h) => h.stamper)),
        avgSleeper: avg(holders.filter((h) => !h.stamper)),
      });
    }

    const st = holders.filter((h) => h.stamper);
    const sl = holders.filter((h) => !h.stamper);
    return {
      rows,
      summary: {
        supplyChangePct: pct(minted - burned, minted),
        stamperChangePct: groupPct(st),
        sleeperChangePct: groupPct(sl),
        nStampers: st.length,
        nSleepers: sl.length,
        burned: toFloat(burned),
      },
    };
  }

  function toFloat(x) {
    return Number((x * 1000n) / ONE) / 1000;
  }
  function avg(group) {
    if (!group.length) return 0;
    return toFloat(group.reduce((a, h) => a + h.balance, 0n)) / group.length;
  }
  function pct(now, start) {
    if (start === 0n) return 0;
    return (Number((now * 10000n) / start) / 10000 - 1) * 100;
  }
  function groupPct(group) {
    if (!group.length) return 0;
    const now = group.reduce((a, h) => a + h.balance, 0n);
    const start = group.reduce((a, h) => a + h.start, 0n);
    return pct(now, start);
  }

  // ---------------------------------------------------------------------
  // Self test
  // ---------------------------------------------------------------------

  function selfTest() {
    const v = global.ROT_VECTORS;
    if (!v) return { ok: false, checked: 0, error: "vectors.js not loaded" };
    let checked = 0;
    try {
      for (const t of v.survival_factor) {
        const got = survivalFactor(BigInt(t.rot_bps), BigInt(t.days));
        if (got !== BigInt(t.value)) {
          throw new Error(
            `survival_factor(${t.rot_bps},${t.days}) = ${got}, contract says ${t.value}`
          );
        }
        checked++;
      }
      for (const t of v.apply_rot) {
        const r = applyRot(BigInt(t.balance), BigInt(t.rot_bps), BigInt(t.days));
        if (r.after !== BigInt(t.after) || r.rotted !== BigInt(t.rotted)) {
          throw new Error(`apply_rot days=${t.days} disagrees`);
        }
        checked++;
      }
      for (const t of v.rot_days) {
        const got = rotDays(BigInt(t.settled), BigInt(t.protected_until), BigInt(t.now));
        if (got !== BigInt(t.value)) throw new Error("rot_days disagrees");
        checked++;
      }
      for (const t of v.stamp_cost) {
        if (stampCost(BigInt(t.balance), BigInt(t.bps)) !== BigInt(t.value)) {
          throw new Error("stamp_cost disagrees");
        }
        checked++;
      }
      for (const t of v.compost_share) {
        const got = compostShare(
          BigInt(t.compost),
          BigInt(t.stake),
          BigInt(t.balance_now),
          BigInt(t.weight)
        );
        if (got !== BigInt(t.value)) throw new Error("compost_share disagrees");
        checked++;
      }
      return { ok: true, checked };
    } catch (e) {
      return { ok: false, checked, error: e.message };
    }
  }

  global.RotModel = {
    BPS,
    PRECISION,
    ONE,
    mulDiv,
    rotDays,
    survivalFactor,
    applyRot,
    stampCost,
    compostShare,
    dayOf,
    epochOf,
    simulate,
    selfTest,
  };
})(window);
